// STM32 Blue Pill — serial counter (USART1, 115200 baud)
unsigned long n = 0;

void setup() {
  Serial.begin(115200);
  pinMode(PC13, OUTPUT);
  Serial.println("STM32 Blue Pill ready");
}

void loop() {
  n++;
  Serial.print("count=");
  Serial.print(n);
  Serial.print("  uptime_ms=");
  Serial.println(millis());
  digitalWrite(PC13, n % 2 ? HIGH : LOW);  // heartbeat
  delay(1000);
}

