// Arduino Uno — receives lines from STM32 on RX (pin 0), blinks LED 13.
String buf;
void setup() {
  Serial.begin(9600);
  pinMode(LED_BUILTIN, OUTPUT);
}
void loop() {
  while (Serial.available()) {
    char c = Serial.read();
    if (c == '\n') {
      Serial.print("[Uno] got: ");
      Serial.println(buf);
      digitalWrite(LED_BUILTIN, !digitalRead(LED_BUILTIN));
      buf = "";
    } else if (c != '\r') {
      buf += c;
    }
  }
}

