// STM32 Blue Pill (F103) — slide switch on PA0 -> onboard PC13 LED
// Switch common (pin 2) -> PA0, ends to GND / 3V3. PC13 LED is active-LOW.
const int SW = PA0;
const int LED = PC13;

void setup() {
  Serial.begin(115200);
  pinMode(SW, INPUT);
  pinMode(LED, OUTPUT);
  Serial.println("Flip the switch");
}

void loop() {
  bool on = (digitalRead(SW) == HIGH);
  digitalWrite(LED, on ? LOW : HIGH);    // switch ON -> LED on
  static int last = -1;
