#include <string.h>

#define EEPROM_BASE_ADDR 0x50
#define EEPROM_SIZE      128

typedef enum {
  ST_IDLE,         /* before any byte after addressing */
  ST_HAS_POINTER,  /* received the pointer byte; further writes are data */
} ee_state;

typedef struct {
  vx_pin a0, a1, a2;
  uint8_t  pointer;
  uint8_t  mem[EEPROM_SIZE];
  ee_state state;
} chip_state_t;

