/*
 * inverter.c — minimal Velxio custom chip
 *
 * Two pins: IN (input) and OUT (output). OUT mirrors the inverse of IN.
 *
 * Build:
 *   bash scripts/compile-chip.sh sdk/examples/inverter.c fixtures/inverter.wasm
 */

#include "velxio-chip.h"
#include <stdlib.h>

typedef struct {
  vx_pin in;
  vx_pin out;
} chip_state_t;

static void on_in_change(void* ud, vx_pin pin, int value) {
  chip_state_t* s = (chip_state_t*)ud;
  vx_pin_write(s->out, value ? VX_LOW : VX_HIGH);
}

void chip_setup(void) {
  chip_state_t* s = (chip_state_t*)malloc(sizeof(chip_state_t));
  s->in  = vx_pin_register("IN",  VX_INPUT);
  s->out = vx_pin_register("OUT", VX_OUTPUT);

  /* Initialize OUT to inverse of current IN state. */
  vx_pin_write(s->out, vx_pin_read(s->in) ? VX_LOW : VX_HIGH);

  /* React to every edge on IN. */
  vx_pin_watch(s->in, VX_EDGE_BOTH, on_in_change, s);

  vx_log("inverter ready");
}

/*
 * reset-gen — power-on reset + control-line pull-ups for a Z80 bus computer
 * (Phase 3, project/multichip-bus/). Holds RESET low at power-on, then drives
 * it HIGH after ~2 ms (a rising edge that releases the CPU). Ties WAIT, BUSREQ,
 * INT and NMI high (deasserted) so the CPU runs freely. Lets a multi-chip Z80
 * machine boot on its own when the user clicks Run.
 */
#include "velxio-chip.h"

static vx_pin reset_;
static vx_timer t;

static void release(void* ud) { (void)ud; vx_pin_write(reset_, 1); }

void chip_setup(void) {
  reset_ = vx_pin_register("RESET", VX_OUTPUT_LOW);   /* hold CPU in reset */
  vx_pin_register("WAIT",   VX_OUTPUT_HIGH);
  vx_pin_register("BUSREQ", VX_OUTPUT_HIGH);
  vx_pin_register("INT",    VX_OUTPUT_HIGH);
  vx_pin_register("NMI",    VX_OUTPUT_HIGH);
  t = vx_timer_create(release, 0);
  vx_timer_start(t, 2000000ULL, false);               /* one-shot, ~2 ms */
}

/*
 * galaksija-keyboard — Galaksija memory-mapped keyboard (Phase 3,
 * project/multichip-bus/). Replicates the scheme used by the libretro Galaksija
 * core: the keyboard occupies addresses 0x2000-0x203F; reading 0x2000+offset
 * returns 0xFE when the key at that matrix offset is pressed, 0xFF otherwise.
 * The chip drives the data bus on a memory READ in that range and exposes
 * set_key(offset, down) for the host to push browser key events. It never
 * drives outside the keyboard range; the paired galaksija-ram releases reads in
 * 0x2000-0x203F so the two never fight for the bus.
 */
#include "velxio-chip.h"
#include <stdint.h>
#include <stdbool.h>

static vx_pin a[14], d[8], rd;
static int rd_last;
static bool driving;
static uint8_t keys[64];

static uint16_t read_addr(void){ uint16_t v=0; for(int i=0;i<14;i++) if(vx_pin_read(a[i])) v|=(1u<<i); return v; }
static int in_range(uint16_t addr){ return (addr & 0x3FC0) == 0x2000; } /* 0x2000-0x203F */
static void drive_data(uint8_t v){ for(int i=0;i<8;i++){ vx_pin_set_mode(d[i],VX_OUTPUT); vx_pin_write(d[i],(v>>i)&1);} driving=true; }
static void release_data(void){ if(!driving) return; for(int i=0;i<8;i++) vx_pin_set_mode(d[i],VX_INPUT); driving=false; }

static void update(void){
