  Serial.println("Files on card:");
  File entry = root.openNextFile();
  while (entry) {
    Serial.printf("  %s  %u bytes\n", entry.name(), (unsigned) entry.size());
    entry.close();
    entry = root.openNextFile();
  }
  root.close();
}

void setup() {
  Serial.begin(115200);
  delay(1200);
  Serial.println("microSD demo - ESP32");

  if (!SD.begin()) {  // default VSPI, CS = GPIO5
    Serial.println("SD.begin() FAILED - check the wiring");
    return;
  }
  Serial.println("Card ready.");
  listRoot();

  File w = SD.open("/log.txt", FILE_WRITE);
  if (w) {
    w.println("hello from velxio");
    w.close();
    Serial.println("Wrote /log.txt");
  }
  File r = SD.open("/log.txt");
  if (r) {
    Serial.print("Read back: ");
    while (r.available()) Serial.write(r.read());
    r.close();
  }
  Serial.println("Done.");
}

void loop() {}

// IR remote -> IR receiver, with no wire between them.
//
// Click a button on the remote (or click the receiver itself, which sends its
// own configured code). Open the Serial Monitor at 9600 baud to see what
// arrived. The receiver's DAT pin carries a real NEC envelope on the board's
// own clock, so IRremote decodes it exactly as it would a physical remote --
// measured on this build: a 9000 us header mark, a 4496 us space, 560 us bit
// marks and 1688 us one-spaces.
//
// DISABLE_LED_FEEDBACK is deliberate. With feedback on, IRremote's ISR also
// toggles pin 13 on every mark, and on this emulated Uno that extra work
// inside the 50 us interrupt makes its state machine complete frames out of
// nothing: the sketch prints a stream of undecodable results with no remote
// anywhere near it. Turning it off costs the blink and nothing else.
//
// Wiring: DAT -> 2   VCC -> 5V   GND -> GND
#include <IRremote.hpp>

const int RECV_PIN = 2;

void setup() {
  Serial.begin(9600);
  IrReceiver.begin(RECV_PIN, DISABLE_LED_FEEDBACK);
  Serial.println(F("Point the remote at the receiver and press a button."));
}

void loop() {
  if (IrReceiver.decode()) {
    if (IrReceiver.decodedIRData.protocol == UNKNOWN) {
      Serial.println(F("received something this build cannot name"));
    } else if (IrReceiver.decodedIRData.flags & IRDATA_FLAGS_IS_REPEAT) {
      Serial.println(F("(key held)"));
    } else {
      Serial.print(F("protocol "));
      Serial.print(getProtocolString(IrReceiver.decodedIRData.protocol));
      Serial.print(F("  address 0x"));
      Serial.print(IrReceiver.decodedIRData.address, HEX);
      Serial.print(F("  command 0x"));
      Serial.println(IrReceiver.decodedIRData.command, HEX);
    }
    IrReceiver.resume();
  }
}

// One remote, two receivers -- which is what infrared does and what no wire
// could express. Both are on their own pin; both hear every button press.
//
// IRremote drives one receiver per sketch, so this times the envelope on each
// pin itself. That is also the honest demonstration: the pins really are
// carrying NEC timing, not a value handed over out of band.
//
// Wiring: receiver A DAT -> 2, receiver B DAT -> 3, both VCC -> 5V, GND -> GND
#include <Arduino.h>

const int PIN_A = 2;
const int PIN_B = 3;

// A demodulator's output is active low: it pulls the line down for each mark.
// So a MARK is the time spent LOW, and the bit value is in the SPACE that
// follows it -- 560 us for a zero, 1690 us for a one.
struct Rx {
  int pin;
  const char *name;
  int lastLevel;
  unsigned long lastEdgeUs;
  unsigned int spaces[34];
  byte n;
  bool inFrame;
};

Rx rxs[2];

void report(Rx &r) {
  unsigned long bits = 0;
  for (byte i = 0; i < 32; i++) {
    if (r.spaces[i + 1] > 1000) bits |= (1UL << i);   // least significant first
  }
  Serial.print(r.name);
  Serial.print(F(": address 0x"));
  Serial.print((uint8_t)(bits & 0xFF), HEX);
  Serial.print(F("  command 0x"));
  Serial.println((uint8_t)((bits >> 16) & 0xFF), HEX);
}

void poll(Rx &r) {
  int now = digitalRead(r.pin);
  if (now == r.lastLevel) return;
  unsigned long t = micros();
  unsigned int w = (unsigned int)(t - r.lastEdgeUs);
  r.lastEdgeUs = t;
  if (now == HIGH) {
    // A LOW that long was the 9 ms header mark: the frame starts here.
    if (!r.inFrame && w > 7000 && w < 11000) {
      r.inFrame = true;
      r.n = 0;
    }
  } else if (r.inFrame) {
    if (r.n < 34) r.spaces[r.n] = w;
    r.n++;
    if (r.n >= 33) {                                  // header space + 32 bits
      report(r);
      r.inFrame = false;
    }
  }
  r.lastLevel = now;
}

void setup() {
  Serial.begin(9600);
  rxs[0] = { PIN_A, "A", HIGH, 0, {}, 0, false };
  rxs[1] = { PIN_B, "B", HIGH, 0, {}, 0, false };
  for (byte i = 0; i < 2; i++) {
    pinMode(rxs[i].pin, INPUT);
    rxs[i].lastLevel = digitalRead(rxs[i].pin);
    rxs[i].lastEdgeUs = micros();
  }
  Serial.println(F("Press a button. Both receivers hear it."));
}

void loop() {
  poll(rxs[0]);
  poll(rxs[1]);
}

// IR remote -> IR receiver on an ESP32. Same link as the Uno example: the
// medium is the air, not a wire, and the envelope is real NEC timing on the
// guest's own clock -- in the browser engine and under QEMU alike.
//
// Wiring: DAT -> GPIO 15   VCC -> 3V3   GND -> GND
#include <IRremote.hpp>

const int RECV_PIN = 15;

void setup() {
  Serial.begin(115200);
  IrReceiver.begin(RECV_PIN, DISABLE_LED_FEEDBACK);
  Serial.println("Point the remote at the receiver and press a button.");
}

void loop() {
  if (IrReceiver.decode()) {
    if (IrReceiver.decodedIRData.protocol == UNKNOWN) {
      Serial.println("received something this build cannot name");
    } else if (IrReceiver.decodedIRData.flags & IRDATA_FLAGS_IS_REPEAT) {
      Serial.println("(key held)");
    } else {
      Serial.printf("protocol %s  address 0x%02X  command 0x%02X\n",
                    getProtocolString(IrReceiver.decodedIRData.protocol),
                    IrReceiver.decodedIRData.address,
                    IrReceiver.decodedIRData.command);
    }
    IrReceiver.resume();
  }
}

// ESP32 + WiFi + MQTT (PubSubClient)
// Joins the emulator AP "Velxio-GUEST", connects to a public MQTT broker,
// then publishes to its own topic and subscribes to it, so every message
// round-trips through the broker and toggles GPIO2. Open the Serial Monitor
// at 115200. Wire an LED to GPIO2 to watch it blink on each round-trip.
#include <WiFi.h>
#include <PubSubClient.h>

const char* WIFI_SSID   = "Velxio-GUEST";   // open AP the emulator advertises
const char* MQTT_BROKER = "broker.hivemq.com";
const int   MQTT_PORT   = 1883;
const int   LED         = 2;

WiFiClient net;
PubSubClient mqtt(net);
String topic;  // unique per board so two ESP32s don't collide

void onMessage(char* t, byte* payload, unsigned int len) {
  String m;
  for (unsigned int i = 0; i < len; i++) m += (char)payload[i];
  Serial.printf("RX [%s]: %s\n", t, m.c_str());
  digitalWrite(LED, !digitalRead(LED));  // toggle on every round-trip
}

void connectWiFi() {
  Serial.printf("WiFi: joining %s ...\n", WIFI_SSID);
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID);
  while (WiFi.status() != WL_CONNECTED) { delay(300); Serial.print("."); }
  Serial.printf("\nWiFi connected, IP %s\n", WiFi.localIP().toString().c_str());
}

void connectMQTT() {
  mqtt.setServer(MQTT_BROKER, MQTT_PORT);
  mqtt.setCallback(onMessage);
  while (!mqtt.connected()) {
    String cid = "velxio-" + String((uint32_t)ESP.getEfuseMac(), HEX);
    Serial.printf("MQTT: connecting to %s as %s ...\n", MQTT_BROKER, cid.c_str());
    if (mqtt.connect(cid.c_str())) {
      Serial.println("MQTT connected");
      mqtt.subscribe(topic.c_str());
      Serial.printf("Subscribed to %s\n", topic.c_str());
    } else {
      Serial.printf("MQTT failed, rc=%d, retry in 2s\n", mqtt.state());
      delay(2000);
    }
  }
}

unsigned long lastPub = 0;
int counter = 0;

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  delay(500);
  topic = "velxio/demo/" + String((uint32_t)ESP.getEfuseMac(), HEX);
  connectWiFi();
  connectMQTT();
}

void loop() {
  if (!mqtt.connected()) connectMQTT();
  mqtt.loop();
  if (millis() - lastPub > 2000) {
    lastPub = millis();
    String msg = "hello " + String(counter++);
    mqtt.publish(topic.c_str(), msg.c_str());
    Serial.printf("TX [%s]: %s\n", topic.c_str(), msg.c_str());
  }
}

// ILI9341 320x240 TFT on ESP32-S3 hardware SPI (FSPI / GPSPI2)
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>

#define TFT_SCK  12
#define TFT_MISO 13
#define TFT_MOSI 11
#define TFT_CS   10
#define TFT_DC    9
#define TFT_RST   8

Adafruit_ILI9341 tft = Adafruit_ILI9341(TFT_CS, TFT_DC, TFT_RST);

void setup() {
  Serial.begin(115200);
  SPI.begin(TFT_SCK, TFT_MISO, TFT_MOSI, TFT_CS);
  tft.begin();
  tft.setRotation(1);

  tft.fillScreen(ILI9341_NAVY);
  tft.fillRoundRect(20, 30, 280, 90, 10, ILI9341_RED);

  tft.setCursor(38, 55);
  tft.setTextColor(ILI9341_WHITE);
  tft.setTextSize(4);
  tft.println("ESP32-S3");

  tft.setCursor(38, 150);
  tft.setTextColor(ILI9341_YELLOW);
  tft.setTextSize(2);
  tft.println("TFT via GPSPI2");

  Serial.println("tft drawn");
}

void loop() {
  delay(2000);
}

